  'tip.stateCost': {
    en: `Just the salary. Parliament also pays a retirement savings top-up and an accident cover fee (the ACC work levy) on it; those are left out.`,
    nl: `Enkel het loon. Het parlement betaalt erop ook een aanvulling voor het pensioensparen en een bijdrage voor de ongevallenverzekering (de ACC work levy); die tellen niet mee.`,
    fr: `Le salaire seul. Le Parlement paie aussi dessus un complément d'épargne retraite et une cotisation d'assurance accidents (l'ACC work levy) ; ils ne sont pas comptés.`,
  },
  'tip.minKs': {
    en: `Not counted for MPs. Instead of the usual 3.5% from an employer, Parliament gives its own top-up to their retirement savings.`,
    nl: `Niet meegeteld voor parlementsleden. In plaats van de gewone 3,5% van een werkgever geeft het parlement een eigen aanvulling op hun pensioensparen.`,
    fr: `Non compté pour les députés. Au lieu des 3,5% habituels d'un employeur, le Parlement verse son propre complément à leur épargne retraite.`,
  },
  'tip.minWff': { en: `Not paid at this income.`, nl: `Niet uitbetaald bij dit inkomen.`, fr: `Non versé à ce niveau de revenu.` },

