  trapTitle: {
    en: (a, b) => `Why so high between ${a} and ${b}?`,
    nl: (a, b) => `Waarom zo hoog tussen ${a} en ${b}?`,
    fr: (a, b) => `Pourquoi si élevé entre ${a} et ${b} ?`,
  },
  trapBody: {
    en: (a, b, kind) => kind === 'wff'
      ? `Working for Families shrinks by 27.5 cents for every dollar the family earns above NZ$44,900. Add 17.5% or 30% income tax and the 1.75% ACC levy, and each extra dollar you earn leaves you only 41 to 53 cents. This lasts until the payments are gone at ${b}. The in-work tax credit is NZ$147 a week this year only; it goes back to NZ$97 from April 2027.`
      : `The independent earner tax credit gives NZ$520 a year back. Between NZ$66,000 and NZ$70,000 it shrinks by 13 cents for every extra dollar you earn. Add 30% income tax and the 1.75% ACC levy, and you keep only 55.25 cents of each extra dollar there: a 44.75% tax rate. Families with children who get Working for Families never get this credit.`,
    nl: (a, b, kind) => kind === 'wff'
      ? `Working for Families daalt met 27,5 cent voor elke dollar die het gezin boven NZ$ 44.900 verdient. Tel daar 17,5% of 30% inkomstenbelasting en de ACC-heffing van 1,75% bij, en van elke extra dollar die je verdient hou je maar 41 tot 53 cent over. Dat duurt tot de steun op is bij ${b}. De in-work tax credit is enkel dit jaar NZ$ 147 per week; vanaf april 2027 weer NZ$ 97.`
      : `De independent earner tax credit geeft je NZ$ 520 per jaar terug. Tussen NZ$ 66.000 en NZ$ 70.000 daalt hij met 13 cent voor elke extra dollar die je verdient. Tel daar 30% inkomstenbelasting en de ACC-heffing van 1,75% bij, en je houdt daar van elke extra dollar maar 55,25 cent over: een belasting van 44,75%. Gezinnen met kinderen die Working for Families krijgen, krijgen dit krediet nooit.`,
    fr: (a, b, kind) => kind === 'wff'
      ? `Working for Families baisse de 27,5 cents pour chaque dollar que la famille gagne au-delà de 44 900 NZ$. Ajoutez 17,5% ou 30% d'impôt et la cotisation ACC de 1,75% : chaque dollar gagné en plus ne vous laisse que 41 à 53 cents. Cela dure jusqu'à ce que les aides s'arrêtent à ${b}. L'in-work tax credit est de 147 NZ$ par semaine cette année seulement ; il revient à 97 NZ$ dès avril 2027.`
      : `L'independent earner tax credit vous rend 520 NZ$ par an. Entre 66 000 NZ$ et 70 000 NZ$, il baisse de 13 cents pour chaque dollar gagné en plus. Ajoutez 30% d'impôt et la cotisation ACC de 1,75% : il ne vous reste que 55,25 cents de chaque dollar en plus, soit un taux de 44,75%. Les familles avec enfants qui reçoivent Working for Families n'y ont jamais droit.`,
  },
  topTitle: {
    en: top => `What changes from ${top}?`,
    nl: top => `Wat verandert er vanaf ${top}?`,
    fr: top => `Qu'est-ce qui change à partir de ${top} ?`,
  },
  topBody: {
    en: (top, gov) => `Above NZ$180,000 a year, each extra dollar is taxed at the top rate of 39%. The ACC levy already stopped at NZ$156,641, so 39% is all you pay on each extra dollar, and it never goes higher.${gov ? ` KiwiSaver members also lose the government's top-up (${gov} a year) once they earn more than NZ$180,000.` : ''}`,
    nl: (top, gov) => `Boven NZ$ 180.000 per jaar wordt elke extra dollar belast tegen het toptarief van 39%. De ACC-heffing stopte al bij NZ$ 156.641, dus 39% is alles wat je op elke extra dollar betaalt, en hoger wordt het nooit.${gov ? ` KiwiSaver-leden verliezen ook de aanvulling van de overheid (${gov} per jaar) zodra ze meer dan NZ$ 180.000 verdienen.` : ''}`,
    fr: (top, gov) => `Au-delà de 180 000 NZ$ par an, chaque dollar en plus est taxé au taux maximal de 39%. La cotisation ACC s'arrête déjà à 156 641 NZ$ : 39% est donc tout ce que vous payez sur chaque dollar en plus, et cela ne monte jamais plus haut.${gov ? ` Les membres de KiwiSaver perdent aussi le complément de l'État (${gov} par an) dès qu'ils gagnent plus de 180 000 NZ$.` : ''}`,
  },

